import { describe, expect, it } from "vitest";
import { encodePrimaryAddress } from "../src/base58";
import { isMyMoneroPhrase, myMoneroKeys, myMoneroPhraseToSeed, MyMoneroPhraseError } from "../src/mymonero";

const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");

// Published vectors from github.com/moneroexamples/mymonero-keys (README, Examples 1 to 3),
// where the keys are stated to agree with those generated by MyMonero. Public test phrases only.
const VECTORS = [
  {
    phrase: "slid otherwise jeers lurk swung tawny zodiac tusks twang cajun swagger peaches tawny",
    seed: "5878efd0a6d45b0374b49c000da07cd2",
    spend: "804f08b84507fb0610910d04ae517c07ae2f38f9330e42e86a50286db16ad60e",
    view: "dbb024c981cf7dc797593713f5f426c3b1cad50542c0814d4786e12e768be504",
  },
  {
    phrase: "nearby hover hiker renting giddy purged chrome paddles point tsunami hoax pledge point",
    seed: "fbdf0efd70ff3c5a321e0f0969041948",
    spend: "bef8b944fdc3eb086b9f0ee4e79aa30ce1510bfd0e45e86891264771de588404",
    view: "8952f17e4378c74fcd99ed6c70e799db60a601edf2685407087cc8c06d4db808",
  },
  {
    phrase: "suddenly opus governing mystery divers obvious royal icon hefty nautical boxes among boxes",
    seed: "852249bca4446e65501cc7f8338027ec",
    spend: "b5f423ed913983229cbdd9af61fa703f4f2d75c0a02bda4c5dbb14ce2913b90c",
    view: "601e6488942149980d9cd50298ef7cdb623cc58e8045f70de994faaea0a97a0e",
  },
];

describe("MyMonero 13-word phrases", () => {
  it.each(VECTORS)("decodes the 16-byte seed: $seed", (v) => {
    expect(hex(myMoneroPhraseToSeed(v.phrase))).toBe(v.seed);
  });

  it.each(VECTORS)("derives MyMonero's spend and view keys: $spend", (v) => {
    expect(myMoneroKeys(v.phrase)).toEqual({ privateSpendKey: v.spend, privateViewKey: v.view });
  });

  it("accepts extra spaces, capitals and 3-letter prefixes", () => {
    const messy = "  SLID other jee lurk swu tawny   zodiac tusks twa cajun swagger peaches TAWNY ";
    expect(myMoneroKeys(messy).privateSpendKey).toBe(VECTORS[0]!.spend);
  });

  it("detects a 13-word phrase", () => {
    expect(isMyMoneroPhrase(VECTORS[0]!.phrase)).toBe(true);
    expect(isMyMoneroPhrase("one two three")).toBe(false);
  });

  it("rejects a wrong checksum word", () => {
    const bad = VECTORS[0]!.phrase.replace(/tawny$/, "zodiac");
    expect(() => myMoneroPhraseToSeed(bad)).toThrowError(MyMoneroPhraseError);
    try { myMoneroPhraseToSeed(bad); } catch (e) { expect((e as MyMoneroPhraseError).code).toBe("CHECKSUM"); }
  });

  it("rejects a word that is not in the list", () => {
    const bad = VECTORS[0]!.phrase.replace("otherwise", "xylophone");
    try { myMoneroPhraseToSeed(bad); throw new Error("should fail"); } catch (e) { expect((e as MyMoneroPhraseError).code).toBe("UNKNOWN_WORD"); }
  });

  it("rejects the wrong number of words", () => {
    try { myMoneroPhraseToSeed("slid otherwise jeers"); throw new Error("should fail"); } catch (e) { expect((e as MyMoneroPhraseError).code).toBe("LENGTH"); }
  });

  it("rejects a swapped word that breaks the encoding or checksum", () => {
    const words = VECTORS[1]!.phrase.split(" ");
    [words[0], words[1]] = [words[1]!, words[0]!];
    expect(() => myMoneroPhraseToSeed(words.join(" "))).toThrowError(MyMoneroPhraseError);
  });
});


describe("Monero address encoding", () => {
  // Public keys and addresses from the same published vectors.
  it.each([
    ["b54264728412c71bb62caca5b3cb57eb96a48a580c97a65257290243e3adf401", "75fc0c90732a3db632bc0a169328067fa3f4c52e80ae067aa60bae8c4ccd8711", "48VWHdLTEpE5dqa5VpAy5xgQWBHZARiGmEmojNLqD4ef1FAzkPxCe9JXUYwCShRR5XNMGnyusrnkmMWr2HMdfDRx2vsrG7c"],
    ["39812cdb0d7f29bc8c70c319cb381b8f943b9a3fa35d40f59e93b63edd012605", "fb227e0e28539fd6ca13fc7d5b2da19307665ae0d152eb87b1239a00c6c66b07", "43oVy226ybWYYA93SExWoLR1tznhhaXRqi5pLtYWhcM3212LriHRkLecvj6zoehqkLRbN9P18LDBGPhP9fHHY7Ar1qi9QDM"],
    ["2c78b799c4d26a2dabb5ceaaff07efff9bd9ffc08cbc9b17634800019f3ca641", "7e9d7fcf3e20a8a3a02f0d73dd676dcc80d0d45c7efdd7d9c783453df150cca3", "43JrWR7mQYh8e4gLAhVeXpjkj5b4RePpv4utgkFt7bpRBxP1t5J4wQKUNNiapRubXSbCwMLZDJ9CJdRjV1m26Kz3KRB4iFJ"],
  ])("encodes %s", (spend, view, address) => {
    expect(encodePrimaryAddress("mainnet", spend, view)).toBe(address);
  });
});
